const DEFAULT_ACCOUNT = 20134;
const STACKED = 'Builds on your applied scenario: these changes are added to the ones already applied.';

const round = (x, dp) => Math.round(x * 10 ** dp) / 10 ** dp;
const clamp = (x, lo, hi) => Math.min(hi, Math.max(lo, x));
const maxOf = (...xs) => { const v = xs.filter(x => x != null); return v.length ? Math.max(...v) : null; };

// Stack a new shock on top of the one already applied, so scenarios are cumulative.
// Lists add up; income multipliers multiply; percentage changes compound. Ranges match the API's
// ShockModel. The engine assesses one duration, so differing durations become the longest one.
// Returns the combined shock plus notes describing any approximation, shown as assumptions.
export function combineShocks(prev, next) {
  const notes = [STACKED];
  const both = (a, b, f) => (a == null ? b ?? null : b == null ? a : f(a, b));
  const compound = (a, b) => ((1 + a / 100) * (1 + b / 100) - 1) * 100;

  let income = both(prev.income_multiplier, next.income_multiplier, (a, b) => a * b);
  if (income != null && income > 1.5) { income = 1.5; notes.push('Combined income is capped at 150% of normal.'); }
  let bills = both(prev.household_bills_pct_change, next.household_bills_pct_change, compound);
  let spending = both(prev.spending_pct_change, next.spending_pct_change, compound);
  if (bills != null && bills !== clamp(bills, -50, 200)) { bills = clamp(bills, -50, 200); notes.push('Combined household bills change is limited to −50% to +200%.'); }
  if (spending != null && spending !== clamp(spending, -50, 200)) { spending = clamp(spending, -50, 200); notes.push('Combined spending change is limited to −50% to +200%.'); }

  let incomeMonths = maxOf(prev.income_duration_months, next.income_duration_months);
  let scenarioMonths = maxOf(prev.scenario_duration_months, next.scenario_duration_months);
  const durations = [prev.income_duration_months, next.income_duration_months,
    prev.scenario_duration_months, next.scenario_duration_months].filter(x => x != null);
  if (new Set(durations).size > 1) {
    const shared = Math.max(...durations);
    if (incomeMonths != null) incomeMonths = shared;
    if (scenarioMonths != null || incomeMonths != null) scenarioMonths = shared;
    notes.push(`The changes had different durations; the combined scenario uses one shared duration of ${shared} months (the longest).`);
  }

  return {
    shock: {
      income_multiplier: income == null ? null : round(income, 4),
      income_duration_months: income == null ? null : incomeMonths,
      household_bills_pct_change: bills == null ? null : round(bills, 2),
